  // Function to play the message through the speaker
  speakMessage(message: string): void {
    const speech = new SpeechSynthesisUtterance(message);
    speech.lang = "en-US";
    speech.volume = 1; // Volume (0 to 1)
    speech.rate = 1; // Rate (0.1 to 10)
    speech.pitch = 1; // Pitch (0 to 2)
    window.speechSynthesis.speak(speech);
  }

  parseChequeCallCount: number = 0;

  ParseCheque(): any {
    this.parseChequeCallCount++;
    const cycle = this.parseChequeCallCount % 5;

    let chequeData: any = {
      date: "24/09/2024",
      amount_in_words: "SIX THOUSANDS ONLY",
      amount_in_number: "2/-",
      payee: "AMNA AMJAD",
      payer: "Title-1 1006682931",
      cheque_number: "40017954",
      account_number: "PK44ALFH0005001006682931",
      bank_name: "Bank Alfalah",
      cross_cheque: false,
      cancelled_cheque: false,
    };

    let scenario = "Complete Valid Cheque";

    // Dynamic scenarios for comprehensive testing:
    switch (cycle) {
      case 1:
        chequeData.payee = "";
        scenario = "Missing Payee (Invalid)";
        break;
      case 2:
        scenario = "Complete Valid Cheque";
        break;
      case 3:
        chequeData.amount_in_words = "";
        scenario = "Missing Amount in Words (Invalid)";
        break;
      case 4:
        chequeData.date = "";
        scenario = "Missing Date (Invalid)";
        break;
      case 0:
        chequeData.amount_in_number = "";
        scenario = "Missing Amount in Number (Invalid)";
        break;
    }

    console.log(
      `[MockService.ParseCheque] Call #${this.parseChequeCallCount} -> Scenario: ${scenario}`,
      chequeData,
    );

    const response: any = {
      statusCode: "00",
      responseMessage: "Success",
      data: {
        filename: "cheque.jpg",
        model: "gemini-3.8-flash",
        data: chequeData,
      },
    };
    return of(response).pipe(delay(200));
  }

